<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Kanban Board</title>
  <style>
    * { box-sizing: border-box; }

    body {
      margin: 0;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      background: #f0f2f5;
      color: #1f2937;
    }

    .app-header {
      background: #ffffff;
      padding: 18px 24px;
      box-shadow: 0 2px 6px rgba(0,0,0,0.06);
      display: flex;
      justify-content: center;
      gap: 12px;
    }

    #new-card {
      flex: 1;
      max-width: 320px;
      padding: 10px 14px;
      border: 1px solid #d1d5db;
      border-radius: 8px;
      font-size: 15px;
      outline: none;
    }

    #new-card:focus {
      border-color: #2563eb;
      box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
    }

    #add-card {
      padding: 10px 20px;
      background: #2563eb;
      color: #fff;
      border: none;
      border-radius: 8px;
      font-size: 15px;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.15s;
    }

    #add-card:hover { background: #1d4ed8; }

    .board {
      display: flex;
      gap: 20px;
      padding: 24px;
      justify-content: center;
      align-items: flex-start;
    }

    .column {
      width: 300px;
      min-height: 420px;
      background: #e5e7eb;
      border-radius: 14px;
      padding: 14px;
      display: flex;
      flex-direction: column;
    }

    .col-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 14px;
    }

    .col-header h2 {
      margin: 0;
      font-size: 15px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      color: #374151;
    }

    .count {
      background: #ffffff;
      color: #374151;
      padding: 4px 10px;
      border-radius: 999px;
      font-size: 13px;
      font-weight: 700;
      box-shadow: 0 1px 2px rgba(0,0,0,0.06);
    }

    .card-list {
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 12px;
      min-height: 60px;
    }

    .card {
      background: #ffffff;
      border-radius: 10px;
      padding: 14px 38px 14px 16px;
      box-shadow: 0 1px 4px rgba(0,0,0,0.08);
      position: relative;
      cursor: grab;
      transition: transform 0.12s, box-shadow 0.12s;
      word-break: break-word;
    }

    .card:hover {
      transform: translateY(-2px);
      box-shadow: 0 6px 10px rgba(0,0,0,0.10);
    }

    .card:active { cursor: grabbing; }

    .card.dragging { opacity: 0.55; }

    .card-title {
      font-size: 14px;
      line-height: 1.4;
    }

    .card-del {
      position: absolute;
      top: 9px;
      right: 9px;
      width: 26px;
      height: 26px;
      background: #fee2e2;
      color: #b91c1c;
      border: none;
      border-radius: 6px;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      font-weight: 700;
      line-height: 1;
      padding: 0;
    }

    .card-del:hover { background: #fecaca; }

    @media (max-width: 980px) {
      .board { flex-direction: column; align-items: center; }
    }
  </style>
</head>
<body>

  <div class="app-header">
    <input type="text" id="new-card" placeholder="Enter a task..." />
    <button id="add-card">Add Card</button>
  </div>

  <div class="board">
    <div class="column" id="col-todo">
      <div class="col-header">
        <h2>To Do</h2>
        <span class="count">0</span>
      </div>
      <div class="card-list"></div>
    </div>

    <div class="column" id="col-doing">
      <div class="col-header">
        <h2>Doing</h2>
        <span class="count">0</span>
      </div>
      <div class="card-list"></div>
    </div>

    <div class="column" id="col-done">
      <div class="col-header">
        <h2>Done</h2>
        <span class="count">0</span>
      </div>
      <div class="card-list"></div>
    </div>
  </div>

  <script>
    (function () {
      const STORAGE_KEY = 'kanbanBoard';
      const cardsById = {};

      const newInput = document.getElementById('new-card');
      const addBtn = document.getElementById('add-card');
      const columns = Array.from(document.querySelectorAll('.column'));

      function updateCounts() {
        columns.forEach(col => {
          const count = col.querySelectorAll('.card').length;
          const countEl = col.querySelector('.count');
          if (countEl) countEl.textContent = count;
        });
      }

      function saveState() {
        try {
          const state = [];
          columns.forEach(col => {
            const colId = col.id;
            col.querySelectorAll('.card').forEach(card => {
              const title = card.querySelector('.card-title').textContent;
              state.push({ id: card.dataset.id, title: title, column: colId });
            });
          });
          localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
        } catch (e) {
          // Storage may be unavailable in some sandboxes; the app still works.
        }
      }

      function createCard(id, title) {
        const card = document.createElement('div');
        card.className = 'card';
        card.draggable = true;
        card.dataset.id = id;

        const titleSpan = document.createElement('span');
        titleSpan.className = 'card-title';
        titleSpan.textContent = title;
        card.appendChild(titleSpan);

        const delBtn = document.createElement('button');
        delBtn.className = 'card-del';
        delBtn.setAttribute('aria-label', 'Delete card');
        delBtn.textContent = '×';
        delBtn.addEventListener('click', function (e) {
          e.stopPropagation();
          delete cardsById[id];
          card.remove();
          updateCounts();
          saveState();
        });
        card.appendChild(delBtn);

        card.addEventListener('dragstart', function (e) {
          e.dataTransfer.setData('text/plain', id);
          e.dataTransfer.effectAllowed = 'move';
          card.classList.add('dragging');
        });

        card.addEventListener('dragend', function () {
          card.classList.remove('dragging');
        });

        cardsById[id] = card;
        return card;
      }

      function addCard() {
        const title = newInput.value.trim();
        if (!title) return;

        const id = 'card-' + Date.now() + '-' + Math.floor(Math.random() * 10000);
        const card = createCard(id, title);
        document.querySelector('#col-todo .card-list').appendChild(card);

        newInput.value = '';
        updateCounts();
        saveState();
      }

      addBtn.addEventListener('click', addCard);
      newInput.addEventListener('keydown', function (e) {
        if (e.key === 'Enter') addCard();
      });

      columns.forEach(col => {
        col.addEventListener('dragover', function (e) {
          e.preventDefault();
          e.dataTransfer.dropEffect = 'move';
        });

        col.addEventListener('drop', function (e) {
          e.preventDefault();
          const id = e.dataTransfer.getData('text/plain');
          const card = cardsById[id];
          if (!card) return;

          col.querySelector('.card-list').appendChild(card);
          updateCounts();
          saveState();
        });
      });

      function loadState() {
        let state = [];
        try {
          const raw = localStorage.getItem(STORAGE_KEY);
          if (raw) state = JSON.parse(raw);
        } catch (e) {
          return;
        }

        if (!Array.isArray(state)) return;

        columns.forEach(col => {
          col.querySelector('.card-list').innerHTML = '';
        });
        Object.keys(cardsById).forEach(key => delete cardsById[key]);

        state.forEach(item => {
          const col = document.getElementById(item.column);
          if (!col) return;
          col.querySelector('.card-list').appendChild(createCard(item.id, item.title));
        });

        updateCounts();
      }

      loadState();
    })();
  </script>
</body>
</html>
